using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Rootborn.Game.StudentLife;
namespace Rootborn.Tests.EditMode.UI.StudentLife{public sealed class LibraryStudyDeskArtTests{[SetUp]public void RequireSavedScenes(){for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)Assert.That(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty,Is.False);EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity",OpenSceneMode.Single);}
[Test]public void DeskUsesReviewedFloorPivotAndCrispSampling(){const string path="Assets/Art/UrbanStreet/Buildings31/library_study_desk.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(96,96)));Assert.That(s.pivot,Is.EqualTo(new Vector2(48,11)));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(i.npotScale,Is.EqualTo(TextureImporterNPOTScale.None));var e=UnityEditor.AddressableAssets.AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(e.address,Is.EqualTo("sprites/town/comfy31/library-study-desk"));}
[Test]public void ExistingStudyPointGetsDedicatedGroundAlignedVisualAndKeepsActivity(){var scene=EditorSceneManager.OpenPreviewScene("Assets/Scenes/Town.unity");try{var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var root=all.Single(t=>t.name=="OutsideActivity_outside_self_study_library");var v=root.Find("Visual").GetComponent<SpriteRenderer>();Assert.That(v.sprite.name,Is.EqualTo("library_study_desk"));Assert.That(root.position,Is.EqualTo(new Vector3(10,2,0)));Assert.That(v.transform.localPosition,Is.EqualTo(new Vector3(0,7f/48f,0)),"Preserve the existing book-centered Visual offset");Assert.That(v.transform.localPosition.y+(4-v.sprite.pivot.y)/48,Is.EqualTo(0).Within(.000001),"Custom pivot compensates original7px offset and places visible feet on the activity-root floor");Assert.That(root.GetComponent<OutsideSchoolActivityInteractor>().Activity.Id,Is.EqualTo("outside.self-study.library"));var box=root.GetComponent<BoxCollider2D>();Assert.That(box.isTrigger,Is.True);Assert.That(box.size.x,Is.EqualTo(.7f).Within(.0001));var helper=all.Single(t=>t.name=="OutsideActivity_outside_help_neighbor");Assert.That(helper.Find("Visual").GetComponent<SpriteRenderer>().sprite.name,Is.EqualTo("neighbor_request_box"));Assert.That(all.SelectMany(t=>t.GetComponents<SpriteRenderer>()).Count(r=>r.sprite!=null&&r.sprite.name=="library_study_desk"),Is.EqualTo(1));}finally{EditorSceneManager.ClosePreviewScene(scene);}}
}}
